import six
from .singleton import ThreadSafeSingleton


@six.add_metaclass(ThreadSafeSingleton)
class NetworkElementValidator:
    """Check if NE is valid."""
    def __init__(self):
        """Basic initialization."""
        self._validators_registry = {}

    def register_validator(self, name_of_element2validate, network_elem_type, variant, validator_function):
        """
        Register 'validator_function' that will be used to validate 'name_of_element2validate' related to 'variant' of 'network_elem_type'.
        That function should return 'value after validation'.

        :Example:

            def ensure_int_id(id_of_variant):
                assert isinstance(id_of_variant, str) or isinstance(id_of_variant, int)
                return int(id_of_variant)
            register_validator('id_of_variant', network_elem_type='UE', variant='wts', validator_function=ensure_int_id)

        :return: None
        """
        assert callable(validator_function)
        self._validators_registry[(name_of_element2validate, network_elem_type, variant)] = validator_function

    def validate(self, network_elem_type, variant, **element2validate):
        """
        Validate 'element2validate' using validator_function registered for 'variant' of 'network_elem_type'.
        If no validator_function registered - just return value of passed in element2validate

        :Example:

            validate(network_elem_type='UE', variant='wts', id_of_variant='7')

        :param element2validate: (must be single key dict) key is 'name_of_element2validate', value is the value to be validated
        :return: value validated&converted by registered validator_function
        """
        name_of_element2validate = list(element2validate.keys())[0]
        value2validate = element2validate[name_of_element2validate]
        requested_validator_key = (name_of_element2validate, network_elem_type, variant)
        if requested_validator_key in self._validators_registry:
            validation_function = self._validators_registry[requested_validator_key]
            validated_value = validation_function(**element2validate)
        else:
            validated_value = value2validate
        return validated_value

    def available_variants(self, name_of_element2validate, network_elem_type):
        """
        Return variants available for given name_of_element2validate & network_elem_type.

        :return: set of variants
        """
        known_variants = []
        for (name_of_element, ne_type, variant) in self._validators_registry:
            if (name_of_element == name_of_element2validate) and (ne_type == network_elem_type):
                known_variants.append(variant)
        return set(known_variants)
